/* Panel B (row 1): Standard errors corrected for spatial dependence (cutoff = 200km) */

/* OLS regressions for the full sample */
eststo acr01: acreg serf_emrate1848_std mills_std $geocontrols1 , spatial latitude(latitude) longitude(longitude) dist(200) bartlett ;
eststo acr02: acreg serf_emrate1848_std mills_std $geocontrols1 $proxcontrols1 , spatial latitude(latitude) longitude(longitude) dist(200) bartlett ;
eststo acr03: acreg serf_emrate1848_std mills_std $geocontrols1 $proxcontrols1 $robcontrols1 , spatial latitude(latitude) longitude(longitude) dist(200) bartlett ;

rename mills_std mills_std_temp ; rename pca_coercion_std pca_coercion_std_temp ;
rename mills_std_east mills_std ; rename pca_coercion_std_east pca_coercion_std ;

/* OLS regressions for the East-Elbia sample */
eststo acr07: acreg serf_emrate1848_std_east mills_std $geocontrols2 if samp_east==1, spatial latitude(latitude) longitude(longitude) dist(200) bartlett ;
eststo acr08: acreg serf_emrate1848_std_east mills_std $geocontrols2 $proxcontrols1 if samp_east==1, spatial latitude(latitude) longitude(longitude) dist(200) bartlett ;
eststo acr09: acreg serf_emrate1848_std_east mills_std $geocontrols2 $proxcontrols1 $robcontrols1 if samp_east==1, spatial latitude(latitude) longitude(longitude) dist(200) bartlett ;

rename mills_std mills_std_east ; rename pca_coercion_std pca_coercion_std_east ;
rename mills_std_temp mills_std ; rename pca_coercion_std_temp pca_coercion_std ;

/* Print results to the table */
estout acr01 acr02 acr03 acr07 acr08 acr09 using "Results/Appendix/TableG10.tex", style(tex) append 
	cells(se(star fmt(3) par([ ]))) keep(mills_std) 
	starlevels(* 0.10 ** 0.05 *** 0.01) 
	varwidth(22) substitute("  -" "$-$") label 
	mlabels(none) collabels(none) varlabels(mills_std "Cutoff = 200km", elist(mills_std "\addlinespace")) 
	posthead("                      &\multicolumn{6}{c}{Panel B: Standard errors corrected for spatial dependence}\\" "\cmidrule{2-7}") ;

tempfile pooled ;
forvalues i = 0/10 { ;
	drop _all ;
	set obs 2 ;
	gen label = "m`i'" in 1 ;
	replace label = "p`i'" in 2 ;

	gen etime = -1 * `i' in 1 ;
	replace etime = `i' in 2 ;

	foreach j in 1 2 { ;
		gen cf_m`j' = .	 ;	

		/* step function for treatment effect */		
		gen truth_m`j' = (0) in 1 ;	
		replace truth_m`j' = (1) in 2 ;
	
		local myb = 0 ;
		cap local myb = myb_ES`j'[1,"D_m`i'"] ;
		gen ES_b_m`j' = `myb' in 1 ;
		local myv = . ;
		cap local myv = myV_ES`j'["D_m`i'","D_m`i'"] ;
		local myse = sqrt(`myv') ;
		gen ES_se_m`j' = `myse' in 1 ;

		local myb = 0 ;
		cap local myb = myb_ES`j'[1,"D_p`i'"] ;
		replace ES_b_m`j' = `myb' in 2 ;
		local myv = . ;
		cap local myv = myV_ES`j'["D_p`i'","D_p`i'"] ;
		local myse = sqrt(`myv') ;
		replace ES_se_m`j' = `myse' in 2 ;
	} ;
	
		
	capture append using `pooled' ;
	save `pooled' , replace ;
} ;

